transforms.code:
rows = value or []
opts = [{"label": r.get("Name") or r.get("Code") or "", "value": r.get("Id")} for r in rows]
return sorted(opts, key=lambda o: o["label"])

customMethods.script:
d = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.setupDraft) or {}
res = BlueRidge.Cutover.Scan.loadSession(d.get("lineLocationId"), d.get("itemId"), d.get("entryRoleCode"), d.get("machineLocationId"), d.get("destinationLocationId"), self.session)
BlueRidge.Common.Ui.notifyResult(res, "Session ready", res.get("Message") if res else None)
if res and res.get("Status"):
	BlueRidge.Cutover.Scan.stepCastDate(0, self.session)
	self.view.custom.forceSetup = False
